import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第三十二卦 恆 雷風恆 震上巽下","description":"周易 - 第三十二卦 恆 雷風恆 震上巽下","frontmatter":{"title":"第三十二卦 恆 雷風恆 震上巽下","description":"周易 - 第三十二卦 恆 雷風恆 震上巽下"},"headers":[],"relativePath":"classics/zhouyi/033.md","filePath":"classics/zhouyi/033.md"}'),l={name:"classics/zhouyi/033.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="恆" tabindex="-1">恆 <a class="header-anchor" href="#恆" aria-label="Permalink to “恆”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>亨，無咎，利貞，利有攸往。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>恆，久也。剛上而柔下，雷風相與，巽而動，剛柔皆應，恆。恆亨無咎，利貞；久於其道也，天地之道，恆久而不已也。利有攸往，終則有始也。日月得天，而能久照，四 時變化，而能久成，聖人久於其道，而天下化成；觀其所恆，而天地萬物之情可見矣！</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>雷風，恆；君子以立不易方。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>浚恆，貞兇，無攸利。象曰：浚恆之兇，始 求深也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>悔亡。象曰：九二悔亡，能久中也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>不恆其德，或承之羞，貞吝。象曰：不恆其德，無所容也。</p><h3 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h3><p>田無禽。象曰：久非其位，安得禽也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>恆其德，貞，婦人吉，夫子兇。象曰：婦人貞吉，從一而終也。夫子制義，從婦兇也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>振恆，兇。象曰：振恆在上，大無功也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
